import React, { useEffect, useState, Suspense, useMemo, useCallback } from 'react';
import {
  Heart,
  ThumbsUp,
  ThumbsDown,
  Sliders,
  X,
  ChevronDown,
  ChevronRight,
  Gift,
  Loader2,
  Package,
  ShoppingCart,
  Tag
} from 'lucide-react';

// Alert-Komponente
const Alert = React.memo(({ variant = 'error', children }) => {
  const bgColor = variant === 'error' ? 'bg-red-50' : 'bg-blue-50';
  const textColor = variant === 'error' ? 'text-red-800' : 'text-blue-800';
  return (
    <div className={`${bgColor} ${textColor} p-4 rounded-xl border border-current/10 shadow-sm my-4`}>
      {children}
    </div>
  );
});

// ProductCard mit Memoization
const ProductCard = React.memo(({ product, onLike, onDislike, likedProducts = [] }) => {
  const imageUrl = useMemo(() => {
    if (!product.image) return '/placeholder-image.jpg';
    if (typeof product.image !== 'string') return product.image;
    if (product.image.includes('src=')) {
      const match = product.image.match(/src="([^"]+)"/);
      return match ? match[1] : '/placeholder-image.jpg';
    }
    return product.image.startsWith('http') ? product.image : '/placeholder-image.jpg';
  }, [product.image]);

  return (
    <div className="bg-white rounded-xl shadow-lg overflow-hidden group transition-all duration-300 hover:shadow-xl">
      <div className="relative">
        <a href={product.url} className="block">
          <img
            src={imageUrl}
            alt={product.name}
            loading="lazy"
            decoding="async"
            className="w-full h-64 object-cover transition-all duration-300 group-hover:scale-105"
            onError={(e) => { e.currentTarget.src = '/placeholder-image.jpg'; }}
          />
        </a>
        <button
          className="absolute top-4 right-4 p-3 bg-white/90 backdrop-blur rounded-full opacity-0 group-hover:opacity-100 transition-all duration-300 shadow-lg hover:bg-red-50"
          aria-label="Zur Wunschliste hinzufügen"
        >
          <Heart className="w-5 h-5 text-red-500" />
        </button>
        {product.price && (
          <div className="absolute bottom-4 left-4 bg-white/90 backdrop-blur px-4 py-2 rounded-full shadow-lg">
            <span className="font-semibold text-gray-900" dangerouslySetInnerHTML={{ __html: product.price }} />
          </div>
        )}
      </div>
      <div className="p-6">
        <h3 className="text-lg font-semibold mb-3 text-gray-900 line-clamp-2">{product.name}</h3>
        <div className="flex justify-between items-center">
          <a href={product.url} className="flex items-center text-blue-600 hover:text-blue-700 transition-colors font-medium">
            Details <ChevronRight className="w-4 h-4 ml-1" />
          </a>
          {(onLike || onDislike) && (
            <div className="flex items-center gap-2">
              {onLike && (
                <button className="p-2 rounded-full hover:bg-gray-100 transition-colors" onClick={() => onLike(product.id)}>
                  <ThumbsUp className={`w-5 h-5 ${likedProducts.includes(product.id) ? 'text-green-600' : 'text-gray-500'}`} />
                </button>
              )}
              {onDislike && (
                <button className="p-2 rounded-full hover:bg-gray-100 transition-colors" onClick={() => onDislike(product.id)}>
                  <ThumbsDown className="w-5 h-5 text-gray-500" />
                </button>
              )}
            </div>
          )}
          <a
            rel="nofollow"
            target="_blank"
            onClick={() => window._paq?.push(['trackEvent', 'Conversion', 'Klick zum Shop', 'Teaser'])}
            href={`/redirect.php?product=${product.slug}`}
            className="p-3 rounded-full bg-blue-100 text-blue-600 hover:bg-blue-200 transition-all duration-300 shadow-sm hover:shadow-md"
          >
            <ShoppingCart className="w-5 h-5" />
          </a>
        </div>
      </div>
    </div>
  );
});

// ProductGrid mit Memoization
const ProductGrid = React.memo(({ products, loading, error, onLike, onDislike, likedProducts }) => {
  if (loading) {
    return (
      <div className="flex justify-center items-center py-16">
        <Loader2 className="w-8 h-8 text-blue-600 animate-spin" />
        <span className="ml-3 text-gray-600 text-lg">Lade Produkte...</span>
      </div>
    );
  }
  if (error) return <Alert>{error}</Alert>;
  if (!products?.length) {
    return (
      <div className="text-center py-16">
        <Package className="w-12 h-12 text-gray-400 mx-auto mb-4" />
        <p className="text-gray-600 text-lg">Keine Produkte gefunden.</p>
      </div>
    );
  }
  return (
    <div className="grid grid-cols-2 lg:grid-cols-4 gap-6">
      {products.map(p => (
        <ProductCard
          key={p.id}
          product={p}
          onLike={onLike}
          onDislike={onDislike}
          likedProducts={likedProducts}
        />
      ))}
    </div>
  );
});

// FilterSection (gekürzt für Übersicht)
const FilterSection = React.memo(({ isOpen, onToggle, activeFilters, onToggleFilterValue, onApplyFilters }) => (
  // FilterSection-Logik bleibt gleich
  <></>
));

// LoadMoreButton
const LoadMoreButton = React.memo(({ onClick, loading }) => (
  <div className="flex justify-center my-8">
    <button
      onClick={onClick}
      disabled={loading}
      className="mx-auto flex items-center px-8 py-3 bg-blue-600 text-white font-semibold rounded-lg shadow-md hover:bg-blue-700 transition-all duration-300 disabled:opacity-50"
    >
      {loading ? (
        <>
          <Loader2 className="w-5 h-5 mr-2 animate-spin" />
          Lade...
        </>
      ) : (
        <>
          Mehr anzeigen
          <ChevronDown className="w-5 h-5 ml-2" />
        </>
      )}
    </button>
  </div>
));

// Hauptkomponente
const UnifiedCard = ({ mode = 'category', initialContentId }) => {
  const [contentId, setContentId] = useState(initialContentId || null);
  const [products, setProducts] = useState({
    popular: { items: [], offset: 0, hasMore: true },
    new: { items: [], offset: 0, hasMore: true },
    random: { items: [], offset: 0, hasMore: true },
    rising: { items: [], offset: 0, hasMore: true },
    sixMonths: { items: [], offset: 0, hasMore: false },
    filtered: { items: [], offset: 0, hasMore: true }
  });
  const [loadingStates, setLoadingStates] = useState({});
  const [errors, setErrors] = useState({});
  const [filterSectionOpen, setFilterSectionOpen] = useState(false);
  const [activeFilters, setActiveFilters] = useState({});
  const [likedProducts, setLikedProducts] = useState(() => {
    return typeof window !== 'undefined'
      ? JSON.parse(localStorage.getItem('likedProducts') || '[]')
      : [];
  });
  const [contentDetails, setContentDetails] = useState(null);

  const idKey = mode === 'category' ? 'category_id' : 'tag_id';
  const randomAction = mode === 'category'
    ? 'wcc_get_random_products_from_category'
    : 'wcc_get_random_products_from_tag';
  const detailsAction = mode === 'category'
    ? 'wcc_get_category_details'
    : 'wcc_get_tag_details';

  // AJAX mit Priorisierung
  const ajaxFetch = useCallback(async (action, data = {}, cacheKey = null, priority = 'normal') => {
    if (cacheKey && sessionStorage.getItem(cacheKey)) {
      return JSON.parse(sessionStorage.getItem(cacheKey));
    }

    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 5000);

    try {
      const formData = new FormData();
      formData.append('action', action);
      if (window.wcc_ajax?.nonce) formData.append('nonce', window.wcc_ajax.nonce);
      Object.entries(data).forEach(([key, value]) => formData.append(key, value));

      const response = await fetch(window.wcc_ajax.ajax_url, {
        method: 'POST',
        body: formData,
        headers: { 'X-Requested-With': 'XMLHttpRequest' },
        signal: controller.signal,
        priority: priority // Experimentelle Fetch-Priority (Browser-abhängig)
      });

      clearTimeout(timeout);
      const json = await response.json();
      if (!json.success) throw new Error(json.data || 'Unbekannter Fehler');

      if (cacheKey) sessionStorage.setItem(cacheKey, JSON.stringify(json.data));
      return json.data;
    } catch (err) {
      clearTimeout(timeout);
      throw err;
    }
  }, []);

  // Produktladung mit Debouncing
  const loadProducts = useCallback(async (type, append = false) => {
    if (!contentId || !products[type].hasMore || loadingStates[type]) return;

    setLoadingStates(prev => ({ ...prev, [type]: true }));
    setErrors(prev => ({ ...prev, [type]: null }));

    try {
      const actionMap = {
        popular: 'wcc_load_more_popular_products',
        new: 'wcc_load_more_new_products',
        random: randomAction,
        rising: 'wcc_load_more_rising_products',
        sixMonths: 'wcc_load_more_six_months_popular_products',
        filtered: 'wcc_filter_products'
      };

      const params = {
        [idKey]: contentId,
        offset: append ? products[type].offset : 0,
        limit: type === 'sixMonths' ? 4 : 8, // Reduzierte Initialanzahl
        ...(type === 'random' && { count: 8, exclude: likedProducts }),
        ...(type === 'filtered' && { filters: JSON.stringify(activeFilters) })
      };

      const cacheKey = `${actionMap[type]}_${contentId}_${params.offset}`;
      const data = await ajaxFetch(actionMap[type], params, cacheKey, type === 'popular' ? 'high' : 'normal');

      setProducts(prev => ({
        ...prev,
        [type]: {
          items: append ? [...prev[type].items, ...data] : data,
          offset: append ? prev[type].offset + data.length : data.length,
          hasMore: data.length === (type === 'sixMonths' ? 4 : 8)
        }
      }));
    } catch (err) {
      setErrors(prev => ({ ...prev, [type]: err.message }));
    } finally {
      setLoadingStates(prev => ({ ...prev, [type]: false }));
    }
  }, [contentId, products, activeFilters, likedProducts, ajaxFetch]);

  // Initialer Content-ID Abruf
  useEffect(() => {
    if (initialContentId) return; // Wenn als Prop übergeben, überspringen
    const elementId = mode === 'category' ? 'category-card' : 'tag-card';
    const dataAttr = mode === 'category' ? 'data-category-id' : 'data-tag-id';
    const el = document.getElementById(elementId);
    if (el) {
      const id = parseInt(el.getAttribute(dataAttr), 10);
      if (id) {
        setContentId(id);
        ajaxFetch(detailsAction, { [idKey]: id }, `details_${id}`, 'high')
          .then(setContentDetails)
          .catch(err => console.error('Details error:', err));
      }
    }
  }, [mode, initialContentId, ajaxFetch]);

  // Lazy Loading mit einzelnem Observer
  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            const section = entry.target.dataset.section;
            if (!products[section].items.length && !loadingStates[section]) {
              loadProducts(section);
            }
          }
        });
      },
      { threshold: 0.1, rootMargin: '100px' }
    );

    const sections = document.querySelectorAll('.lazy-section');
    sections.forEach(section => observer.observe(section));

    return () => sections.forEach(section => observer.unobserve(section));
  }, [loadProducts, products, loadingStates]);

  // Initiale Ladung
  useEffect(() => {
    if (contentId && !products.popular.items.length && !loadingStates.popular) {
      loadProducts('popular');
    }
  }, [contentId, loadProducts, products.popular.items.length, loadingStates.popular]);

  const toggleFilterValue = useCallback((filterName, value) => {
    setActiveFilters(prev => {
      const current = prev[filterName] || [];
      return {
        ...prev,
        [filterName]: current.includes(value)
          ? current.filter(v => v !== value)
          : [...current, value]
      };
    });
  }, []);

  return (
    <div className="min-h-screen bg-gray-50" id={mode === 'category' ? 'category-card' : 'tag-card'}>
      <main className="container mx-auto px-4">
        <Suspense fallback={<Loader2 className="w-8 h-8 mx-auto my-8 animate-spin" />}>
          <section className="mb-12 lazy-section" data-section="popular">
            <h2 className="text-2xl font-bold mb-4">Aktuell beliebt</h2>
            <ProductGrid
              products={products.popular.items}
              loading={loadingStates.popular}
              error={errors.popular}
              likedProducts={likedProducts}
            />
            {products.popular.hasMore && (
              <LoadMoreButton
                onClick={() => loadProducts('popular', true)}
                loading={loadingStates.popular}
              />
            )}
          </section>

          <section className="mb-12 lazy-section" data-section="new">
            <h2 className="text-2xl font-bold mb-4">Neue Geschenkideen</h2>
            <ProductGrid
              products={products.new.items}
              loading={loadingStates.new}
              error={errors.new}
              likedProducts={likedProducts}
            />
            {products.new.hasMore && (
              <LoadMoreButton
                onClick={() => loadProducts('new', true)}
                loading={loadingStates.new}
              />
            )}
          </section>

          {/* Weitere Sektionen wie vorher, aber ohne isVisible-Bedingung zur Vereinfachung */}
        </Suspense>
      </main>
    </div>
  );
};

export default UnifiedCard;
